pipeline {
    agent any

    environment {
        GROUP_NAME = null
        PROJECT_NAME = null
        VERSION = null
        PORT=8001
        DOCKER_REGISTRY = '10.0.0.59:15000' // 替换为你的Docker仓库地址
        REMOTE_HOST = '10.0.0.41' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // Jenkins中保存的远程服务器SSH凭证ID
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: 'ssh://git@106.227.89.18:10093/openData/shujuzhilihd.git']])
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file: 'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = pom.artifactId
                    VERSION = pom.version
                    sh 'sed -i \'s/namespace: .*$/namespace: test/\' DataGovernance/src/main/resources/bootstrap.yml'
                    sh 'sed -i \'s/group: .*$/group: DEFAULT_GROUP/\' DataGovernance/src/main/resources/bootstrap.yml'
                    sh 'sed -i \'s/active: .*$/active: test/\' DataGovernance/src/main/resources/bootstrap.yml'
					sh 'sed -i \'s/server: .*$/server: 10.0.0.54:8848/\' DataGovernance/src/main/resources/bootstrap.yml'
                    sh "mvn install -Dmaven.test.skip=true"
                    //sh "mvn install -Dmaven.test.skip=true clean package "
                }
            }
        }

        stage('Build Image') {
            steps {
                script {
                    try {
                        echo 'try to remove old image before build.'
                        sh "docker rmi ${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"
                        echo 'old image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}) removed.'
                    } catch (Exception e) {
                        echo 'nothing to remove.'
                    }



                    echo 'try to build the image.'
                    sh "docker build -t ${GROUP_NAME}/${PROJECT_NAME}:${VERSION} -f \"devops/Dockerfile\" --build-arg group_name=${GROUP_NAME} --build-arg project_name=${PROJECT_NAME} --build-arg version=${VERSION} --build-arg port=${PORT} ."
                    echo 'image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}) is built.'
                }
            }
        }


        stage('Push Image') {
            steps {
                script {
                    try{
                    def timestamp = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
                        sh " docker login --username=admin --password=bigdata888888 10.0.0.59:15000"
                        sh " docker tag ${GROUP_NAME}/${PROJECT_NAME}:${VERSION} 10.0.0.59:15000/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        sh " docker push 10.0.0.59:15000/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}"
                        echo "image(${GROUP_NAME}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP}) is pushed to the registry."
                    } catch (Exception e) {
                        echo 'push image failed'
                        echo "Caught exception: ${e.getMessage()}"
                    }
                }
            }
        }

         stage('Deploy to Remote') {
            steps {
                script {
                    if (params.DEPLOY) {
                        sshagent([REMOTE_CREDENTIALS_ID]) {
                            sh """
                                ssh ${REMOTE_USER}@${REMOTE_HOST} '
                                docker login -u admin -p bigdata888888 10.0.0.59:15000 &&
                                docker pull ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} &&
                                docker stop ${PROJECT_NAME} || true &&
                                docker rm ${PROJECT_NAME} || true &&
                                docker run -d --name ${PROJECT_NAME} -p ${PORT}:${PORT} --network=host -e TZ=Asia/Shanghai ${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${env.TIMESTAMP} 
                                '
                               """
                               echo 'sh complete!'
                        }
                    } else {
                        echo 'deploy skipped.'
                    }
                }
            }
        }
    }

}
